package com.rtsbuilding.rtsbuilding.client.rendering.builder;
import com.rtsbuilding.rtsbuilding.client.screen.shape.ShapeDataRecords;import com.rtsbuilding.rtsbuilding.platform.block.BlockState;import net.minecraft.client.Minecraft;import com.rtsbuilding.rtsbuilding.platform.render.BufferBuilder;import net.minecraft.init.Blocks;import com.rtsbuilding.rtsbuilding.platform.math.EnumFacing;import com.rtsbuilding.rtsbuilding.platform.math.BlockPos;import java.util.*;
/**
 * 已确认破坏工作的合并骨架缓存。1.12 版按方块长坐标维护待删除集合；服务器确认后只重建
 * 剩余外层方块，避免每帧重新扫描世界，也保留完成淡出的最后快照。
 */
public final class MergedSkeletonRenderer{
 private static Cache cache=Cache.EMPTY;private static final Set<Long>PENDING=new HashSet<Long>();private static final Map<Long,Integer>RECHECK=new HashMap<Long,Integer>();private static final int MAX_FILL=768,MAX_EDGES=131072,RECHECK_FRAMES=8;private MergedSkeletonRenderer(){}
 public static void markDestroyed(BlockPos p){if(p!=null)PENDING.add(p.toLong());}static void clearCache(){cache=Cache.EMPTY;PENDING.clear();RECHECK.clear();}
 static boolean hasCachedSkeleton(ShapeDataRecords.GhostPreview p){return cache.matches(p)&&!cache.edges.isEmpty();}static boolean hasSkeletonCacheForPreview(ShapeDataRecords.GhostPreview p){return cache.matches(p);}
 static boolean renderCachedSkeleton(ShapeDataRecords.GhostPreview p,BufferBuilder l,BufferBuilder f,float progress,float lineA,float fillA,float alpha){if(!cache.matches(p))return false;applyPending();render(cache,progress,fillA,alpha);return true;}
 static void renderMergedSkeletonFast(ShapeDataRecords.GhostPreview p,BufferBuilder l,BufferBuilder f,float progress,float lineA,float fillA,float alpha){Cache c=get(p);applyPending();render(c,progress,fillA,alpha);}
 static void renderMergedSkeletonSnapshot(ShapeDataRecords.GhostPreview p,BufferBuilder l,BufferBuilder f,float progress,float lineA,float fillA,float alpha){renderMergedSkeletonFast(p,l,f,progress,lineA,fillA,alpha);}
 static void renderConfirmedDestroyWorkArea(ShapeDataRecords.GhostPreview p,BufferBuilder l,BufferBuilder f,float progress,float alpha){renderMergedSkeletonFast(p,l,f,progress,.30F,.035F,alpha);}
 static void renderConfirmedRangeDestroy(ShapeDataRecords.GhostPreview p,BufferBuilder l,BufferBuilder f,float progress,float alpha){renderConfirmedDestroyWorkArea(p,l,f,progress,alpha);}
 private static Cache get(ShapeDataRecords.GhostPreview p){if(!cache.matches(p))cache=build(p);return cache;}
 /** 测试与渲染共享的缓存读取边界；消费本帧已破坏位置后再返回新轮廓。 */
 private static Cache getCachedSkeleton(ShapeDataRecords.GhostPreview p){get(p);applyPending();return cache;}
 private static Cache build(ShapeDataRecords.GhostPreview p){List<BlockPos>src=p==null?Collections.<BlockPos>emptyList():p.blocks();LinkedHashMap<Long,BlockPos>remaining=new LinkedHashMap<Long,BlockPos>();if(src!=null)for(BlockPos q:src)if(q!=null)remaining.put(q.toLong(),q);return rebuild(p,key(p),remaining);}
 private static void applyPending(){if(cache==Cache.EMPTY)return;boolean changed=false;for(Long k:PENDING){BlockPos removed=cache.remaining.remove(k);changed|=removed!=null;if(removed!=null)for(EnumFacing side:EnumFacing.values())RECHECK.put(removed.offset(side).toLong(),RECHECK_FRAMES);}PENDING.clear();Iterator<Map.Entry<Long,Integer>>it=RECHECK.entrySet().iterator();while(it.hasNext()){Map.Entry<Long,Integer>e=it.next();BlockPos p=BlockPos.fromLong(e.getKey());if(cache.remaining.containsKey(e.getKey())&&!isLive(p)){cache.remaining.remove(e.getKey());changed=true;it.remove();}else if(e.getValue()<=1)it.remove();else e.setValue(e.getValue()-1);}if(changed)cache=rebuild(cache.preview,cache.key,cache.remaining);}
 private static boolean isLive(BlockPos p){Minecraft mc=Minecraft.getMinecraft();if(mc==null||mc.theWorld==null||!com.rtsbuilding.rtsbuilding.platform.world.WorldCompat.isBlockLoaded(mc.theWorld, p,false))return true;BlockState s=BlockState.fromWorld(mc.theWorld, p);return s.getBlock()!=Blocks.air&&!s.getMaterial().isLiquid()&&s.getBlockHardness(mc.theWorld,p)>=0;}
 private static Cache rebuild(ShapeDataRecords.GhostPreview p,int key,LinkedHashMap<Long,BlockPos>remaining){List<BlockPos>outer=new ArrayList<BlockPos>();Set<Long>keys=remaining.keySet();for(BlockPos q:remaining.values())for(EnumFacing side:EnumFacing.values())if(!keys.contains(q.offset(side).toLong())){outer.add(q);break;}List<BlockPos>fill=remaining.size()<=MAX_FILL?outer:Collections.<BlockPos>emptyList();/* 轮廓提取必须看到完整实体；只传外层方块会把被省略的内部块误判为空洞。 */List<UltimineBlockMerger.EdgeLine>edges=UltimineBlockMerger.getEdgeLines(remaining.values());if(edges.size()>MAX_EDGES)edges=new ArrayList<UltimineBlockMerger.EdgeLine>(edges.subList(0,MAX_EDGES));return new Cache(p,key,new LinkedHashMap<Long,BlockPos>(remaining),edges,fill);}
 private static void render(Cache c,float progress,float fillA,float alpha){UltimineGhostRenderer.renderGeometry(c.edges,c.fill,progress,fillA,alpha);}
 private static int key(ShapeDataRecords.GhostPreview p){if(p==null||p.blocks()==null)return 0;int h=1;for(BlockPos q:p.blocks())h=31*h+(q==null?0:(int)(q.toLong()^(q.toLong()>>>32)));return h;}
 private static final class Cache{static final Cache EMPTY=new Cache(null,0,new LinkedHashMap<Long,BlockPos>(),Collections.<UltimineBlockMerger.EdgeLine>emptyList(),Collections.<BlockPos>emptyList());final ShapeDataRecords.GhostPreview preview;final int key;final LinkedHashMap<Long,BlockPos>remaining;final List<UltimineBlockMerger.EdgeLine>edges;final List<BlockPos>fill;Cache(ShapeDataRecords.GhostPreview p,int k,LinkedHashMap<Long,BlockPos>r,List<UltimineBlockMerger.EdgeLine>e,List<BlockPos>f){preview=p;key=k;remaining=r;edges=e;fill=f;}boolean matches(ShapeDataRecords.GhostPreview p){return p!=null&&(p==preview||key==key(p));}}
}
